using System.Data.SQLite;

namespace DesignLibrary.LibraryFormat;

internal class DesignSearch
{
	public static SQLiteCommand SqlCreate()
	{
		return new SQLiteCommand("\r\n            CREATE TABLE IF NOT EXISTS [DesignSearch] \r\n\t            (\r\n  \t            [DesignId] integer PRIMARY KEY NOT NULL,\r\n                [Version] integer NOT NULL,\r\n\t            [SPINumber] varchar(255)  NULL,\r\n\t            [SeriesNumber] varchar(50)  NULL,\r\n\t            [LastUpdateDate] datetime  NULL,\r\n\t            [PrimaryDesignComponentId] INTEGER  NULL,\r\n\t            [ComponentId] integer  NULL,\r\n\t            [DefaultStyle] nvarchar(50)  NULL,\r\n\t            [DefaultStyleElement] nvarchar(50)  NULL,\r\n\t            [SecondaryStyleElement] nvarchar(50)  NULL,\r\n\t            [PrimaryDesignComponentCenterGemSetting] nvarchar(50)  NULL,\r\n\t            [IsIncludedWithBaseDesigns] INTEGER  NULL,\r\n\t            [Is3CDesign] INTEGER  NULL,\r\n\t            [Designer] varchar(255)  NULL,\r\n\t            [IsBaseDesign] INTEGER  NULL,\r\n\t            [IsVariantDesign] INTEGER  NULL,\r\n\t            [IsNewDesign] INTEGER  NULL,\r\n                [IsFreeHandPart] INTEGER NULL,\r\n                [IsFreeHandPartWithGem] INTEGER NULL,\r\n                [IsStaticFreeHandPart] INTEGER NULL,\r\n\t            [StullerBaseNo] varchar(255) NULL,\r\n\t            [DefaultSettingTypeOrder] INTEGER  NULL,\r\n\t            [DefaultStyleElementOrder] INTEGER  NULL,\r\n\t            [DefaultStyleOrder] INTEGER  NULL,\r\n\t            [SecondaryStyleElementOrder] INTEGER  NULL,\r\n\t            [CenterGemMinLength] decimal NULL,\r\n\t            [CenterGemMaxLength] decimal NULL,\r\n\t            [CenterGemMinWidth] decimal NULL,\r\n\t            [CenterGemMaxWidth] decimal NULL,\r\n\t            CONSTRAINT [FK_DesignSearch_0] FOREIGN KEY ([DesignId]) REFERENCES [Designs] ([DesignId])\r\n\t            );\r\n\r\n                DELETE FROM [DesignSearch];\r\n                \r\n\r\n                CREATE VIEW IF NOT EXISTS [View_DesignSearch] AS                 \r\n            \tSELECT\r\n                        Designs.DesignId AS DesignId, Designs.Version AS Version,Designs.StullerNo AS SPINumber, Designs.SeriesNumber AS SeriesNumber, Designs.LastUpdateDate AS LastUpdateDate, \r\n\t\t\t\t\t\t\t (SELECT        DesignComponentId\r\n\t\t\t\t\t\t\t   FROM            DesignComponents\r\n\t\t\t\t\t\t\t   WHERE        (DesignId = Designs.DesignId) AND (ComponentId = 1 OR\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t ComponentId = 4) LIMIT 1) AS PrimaryDesignComponentId,\r\n\t\t\t\t\t\t\t (SELECT        ComponentId\r\n\t\t\t\t\t\t\t   FROM            DesignComponents AS DesignComponents_2\r\n\t\t\t\t\t\t\t   WHERE        (DesignId = Designs.DesignId) AND (ComponentId = 1 OR\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t ComponentId = 4) LIMIT 1) AS ComponentId,\r\n\t\t\t\t\t\t\t (SELECT        Attribute.AttributeName\r\n\t\t\t\t\t\t\t   FROM            DesignAttributes INNER JOIN\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t Attribute ON DesignAttributes.AttributeId = Attribute.AttributeID\r\n\t\t\t\t\t\t\t   WHERE        (DesignAttributes.DesignId = Designs.DesignId) AND (Attribute.AttributeTypeID = 12) LIMIT 1) AS DefaultStyle,\r\n\t\t\t\t\t\t\t (SELECT        Attribute_1.AttributeName\r\n\t\t\t\t\t\t\t   FROM         DesignAttributes AS DesignAttributes_1 INNER JOIN\r\n\t\t\t\t\t\t\t\t\t\t\t\t   Attribute AS Attribute_1 ON DesignAttributes_1.AttributeId = Attribute_1.AttributeID\r\n\t\t\t\t\t\t\t   WHERE       (DesignAttributes_1.DesignId = Designs.DesignId) AND (Attribute_1.AttributeTypeID = 13) AND (DesignAttributes_1.AttributeValue = 'IsPrimary') LIMIT 1) AS DefaultStyleElement,\r\n\t\t\t\t\t\t\t (SELECT        Attribute_2.AttributeName\r\n\t\t\t\t\t\t\t   FROM         DesignAttributes AS DesignAttributes_2 INNER JOIN\r\n\t\t\t\t\t\t\t\t\t\t\t\t   Attribute AS Attribute_2 ON DesignAttributes_2.AttributeId = Attribute_2.AttributeID\r\n\t\t\t\t\t\t\t   WHERE       (DesignAttributes_2.DesignId = Designs.DesignId) AND (Attribute_2.AttributeTypeID = 13) AND (DesignAttributes_2.AttributeValue <> 'IsPrimary') ORDER BY Attribute_2.AttributeCSOrder  LIMIT 1) AS SecondaryStyleElement,\r\n\t\t\t\t\t\t\t (SELECT        Attribute_4.AttributeName\r\n\t\t\t\t\t\t\t   FROM         DesignAttributes INNER JOIN DesignComponents AS DesignComponents_1 ON\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t (DesignAttributes.ComponentId = DesignComponents_1.ComponentId AND DesignAttributes.DesignId = DesignComponents_1.DesignId)\r\n\t\t\t\t\t\t\t\tINNER JOIN\tAttribute AS Attribute_4 ON DesignAttributes.AttributeId = Attribute_4.AttributeID\r\n\t\t\t\t\t\t\t   WHERE        (DesignComponents_1.DesignId = Designs.DesignId) AND (Attribute_4.AttributeTypeID = 9) AND (DesignComponents_1.ComponentId = 1 OR DesignComponents_1.ComponentId = 4) LIMIT 1) AS PrimaryDesignComponentCenterGemSetting,\r\n\t\t\t\t\t\t\t (CASE WHEN EXISTS\r\n\t\t\t\t\t\t\t (SELECT        DesignAttributes.DesignAttributeId\r\n\t\t\t\t\t\t\t   FROM         DesignAttributes\r\n\t\t\t\t\t\t\t   WHERE        DesignId = Designs.DesignId AND AttributeId = 287) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END) AS IsIncludedWithBaseDesigns,\r\n\t\t\t\t\t\t\t (CASE WHEN EXISTS\r\n                             (SELECT        DesignAttributes.DesignAttributeId\r\n\t\t\t\t\t\t\t   FROM         DesignAttributes\r\n\t\t\t\t\t\t\t   WHERE        DesignId = Designs.DesignId AND AttributeId = 358 AND AttributeValue <> '0') THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END) AS Is3CDesign,\r\n\r\n\r\n                        Designs.Designer AS Designer,\r\n\t\t\t\t\t        CASE WHEN Designs.DesignTypeId =0 THEN CAST(1 AS Integer) ELSE CAST(0 AS Integer) END AS IsBaseDesign,\r\n\t\t\t\t\t\tCASE WHEN Designs.DesignTypeId >0 THEN CAST(1 AS Integer) ELSE CAST(0 AS Integer) END AS IsVariantDesign,\r\n\t\t\t\t\t\tCASE WHEN Designs.FirstReleaseLibraryId = (select version from libraryVersion) THEN CAST(1 AS Integer) ELSE CAST(0 AS Integer) END AS IsNewDesign,\r\n                        CASE WHEN (SELECT attributevalue from designattributes where designattributes.designid=designs.designid and attributeid=428 LIMIT 1) = 'CP' THEN CAST(1 AS Integer) ELSE CAST(0 AS Integer) END AS IsFreeHandPart,\r\n                        CASE WHEN (SELECT attributevalue from designattributes where designattributes.designid=designs.designid and attributeid=428 LIMIT 1) = 'CPG' THEN CAST(1 AS Integer) ELSE CAST(0 AS Integer) END AS IsFreeHandPartWithGem,\r\n                        CASE WHEN (SELECT attributevalue from designattributes where designattributes.designid=designs.designid and attributeid=428 LIMIT 1) = 'SP' THEN CAST(1 AS Integer) ELSE CAST(0 AS Integer) END AS IsStaticFreeHandPart,\r\n\t\t\t\t\t\tSubstr(Designs.StullerNo,1,8) AS StullerBaseNo,\r\n\t\t\t\t\t\t(SELECT CAST(999 AS Integer)) AS DefaultSettingTypeOrder,\r\n\t\t\t\t\t\t(SELECT CAST(999 AS Integer)) AS DefaultStyleElementOrder,\r\n\t\t\t\t\t\t(SELECT CAST(999 AS Integer)) AS DefaultStyleOrder,\r\n\t\t\t\t\t\t(SELECT CAST(999 AS Integer)) AS SecondaryStyleElementOrder,\r\n\t\t\t\t\t\t(SELECT GemXMin FROM DesignGems WHERE GemPlacement = 1 AND DesignGems.Designid = Designs.DesignId LIMIT 1) AS CenterGemMinLength,\r\n\t\t\t\t\t\t(SELECT GemXMax FROM DesignGems WHERE GemPlacement = 1 AND DesignGems.Designid = Designs.DesignId LIMIT 1) AS CenterGemMaxLength,\r\n\t\t\t\t\t\t(SELECT GemYMin FROM DesignGems WHERE GemPlacement = 1 AND DesignGems.Designid = Designs.DesignId LIMIT 1) AS CenterGemMinWidth,\r\n\t\t\t\t\t\t(SELECT GemYMax FROM DesignGems WHERE GemPlacement = 1 AND DesignGems.Designid = Designs.DesignId LIMIT 1) AS CenterGemMaxWidth\r\n\t                FROM            Designs WHERE CSGLFound=1\r\n              ");
	}

	public static string SqlIndex()
	{
		return "\r\n                CREATE INDEX IF NOT EXISTS [IDX_DesignSearch_DesignId] ON [DesignSearch]( [DesignId]  ASC );\r\n                CREATE INDEX IF NOT EXISTS [IDX_DesignSearch_SPINumber] ON [DesignSearch]( [SPINumber]  ASC );\r\n                ";
	}

	public static string[] SqlInsert()
	{
		return new string[2]
		{
			"DesignSearch",
			string.Empty
		};
	}
}
